using System.ComponentModel;
using System.Net.Http.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API by resource path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The API resource path to fetch (e.g. \"users/1\")")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching external API resource: {Path}", path);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Successfully fetched {Length} chars from {Path}", content.Length, path);

        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the given text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        yield return new ChatMessage(
            ChatRole.User,
            $"""
            Please provide a {style} summary of the following text:

            ---
            {text}
            ---
            """);
    }
}

